mapper.update:
update pro_card_process
set input_time = ifnull(input_time, #{inputTime}),
    quantity_input = ifnull(quantity_input, 0) + #{input},
    update_by = #{updateBy},
    update_time = #{updateTime}
where record_id = #{recordId}

update pro_card_process
set output_time = case when ifnull(quantity_output, 0) <= #{output}
                       then null else output_time end,
    quantity_output = greatest(ifnull(quantity_output, 0) - #{output}, 0),
    quantity_unqualified = greatest(ifnull(quantity_unqualified, 0) - #{unqualified}, 0),
    update_by = #{updateBy},
    update_time = #{updateTime}
where record_id = #{recordId}

update pro_card_process
set input_time = case when ifnull(quantity_input, 0) <= #{input}
                      then null else input_time end,
    quantity_input = greatest(ifnull(quantity_input, 0) - #{input}, 0),
    update_by = #{updateBy},
    update_time = #{updateTime}
where record_id = #{recordId}
